+async function consumeRateLimit(
+  database: D1Database,
+  key: string,
+  rule: { max: number; window: number },
+) {
+  const now = Date.now();
+  const windowMilliseconds = rule.window * 1000;
+  const bucket = await database
+    .prepare(
+      `INSERT INTO rate_limit_buckets
+        (bucket_key, window_started_at, count, updated_at)
+       VALUES (?, ?, 1, ?)
+       ON CONFLICT(bucket_key) DO UPDATE SET
+         count = CASE
+           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN 1
+           ELSE rate_limit_buckets.count + 1
+         END,
+         window_started_at = CASE
+           WHEN rate_limit_buckets.window_started_at + ? <= ? THEN ?
+           ELSE rate_limit_buckets.window_started_at
+         END,
+         updated_at = ?
+       RETURNING count, window_started_at`,
+    )
+    .bind(key, now, now, windowMilliseconds, now, windowMilliseconds, now, now, now)
+    .first<{ count: number; window_started_at: number }>();
+
+  if (!bucket) return { allowed: false, retryAfter: rule.window };
+
+  if (bucket.count === 1) {
+    const db = createDb(database);
+    await db
+      .delete(rateLimitBuckets)
+      .where(lt(rateLimitBuckets.updatedAt, now - 24 * 60 * 60 * 1000))
+      .run();
+  }
+
+  const retryAfter = Math.max(
+    0,
+    Math.ceil((bucket.window_started_at + windowMilliseconds - now) / 1000),
+  );
+
+  return {
+    allowed: bucket.count <= rule.max,
+    retryAfter,
+  };
+}
+
+async function recordAuthAudit(
+  database: ReturnType<typeof createDb>,
+  eventType: string,
+  userId: string,
+  metadata: Record<string, unknown>,
+) {
+  const principal = await database
+    .select({ principalId: humanPrincipals.principalId })
+    .from(humanPrincipals)
+    .where(eq(humanPrincipals.userId, userId))
+    .get();
+
+  const now = Date.now();
+  await database
+    .insert(auditEvents)
+    .values({
+      id: `${eventType}:${userId}:${now}:${crypto.randomUUID()}`,
+      eventType,
+      actorPrincipalId: principal?.principalId ?? null,
+      subjectPrincipalId: principal?.principalId ?? null,
+      subjectUserId: userId,
+      metadata: JSON.stringify(metadata),
+      createdAt: now,
+    })
+    .onConflictDoNothing()
+    .run();
+}
+
+async function requireActiveHuman(
+  database: ReturnType<typeof createDb>,
+  userId: string,
+  emailVerified: boolean,
+) {
+  if (!emailVerified) throw new Error("Verified human required.");
+
+  const activePrincipal = await database
+    .select({ ok: sql<number>`1` })
+    .from(humanPrincipals)
+    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
+    .where(
+      and(
+        eq(humanPrincipals.userId, userId),
+        eq(humanPrincipals.status, "active"),
+        eq(humanPrincipals.disabled, false),
+        eq(principals.type, "human"),
+        eq(principals.status, "active"),
+      ),
+    )
+    .get();
+
+  if (activePrincipal?.ok !== 1) throw new Error("Active human principal required.");
+}
